const responsibilityHoursData = useMemo(() => {
    const respMap = new Map<string, number>()
    submissions.forEach(s => {
        const title = s.assignment?.responsibility?.title || 'Unknown'
        const hours = s.hoursWorked || 0
        respMap.set(title, (respMap.get(title) || 0) + hours)
    })
    const entries = Array.from(respMap.entries())
        .filter(([, hours]) => hours > 0)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10) // Top 10 responsibilities

    return {
        series: [{ name: 'Hours', data: entries.map(([, hours]) => Math.round(hours * 10) / 10) }],
        categories: entries.map(([title]) => title.length > 25 ? title.substring(0, 22) + '...' : title)
    }
}, [submissions])

